"""Route path matching and dictionary consolidation."""
from typing import Dict, Any, List

def deep_merge_matchers(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    res = dict(base)
    for k, v in override.items():
        if k in res:
            if isinstance(res[k], dict) and isinstance(v, dict):
                res[k] = deep_merge_matchers(res[k], v)
            elif isinstance(res[k], list) and isinstance(v, list):
                # Rule H12: Concatenate lists with deduplication, preserving first-seen order.
                merged_list = []
                seen = set()
                # Process base items first
                for item in res[k]:
                    if item not in seen:
                        merged_list.append(item)
                        seen.add(item)
                # Then process override items
                for item in v:
                    if item not in seen:
                        merged_list.append(item)
                        seen.add(item)
                res[k] = merged_list
            else:
                # For other types, or if types don't match, override completely.
                res[k] = v
        else:
            # If key not in base, simply add it from override.
            res[k] = v
    return res

def normalize_prefix(path: str) -> str:
    return "/" + path.strip("/")
